public class AppendSingleSkill
{
    public static void Execute(string chart_id, string x_value, string y_value)
    {
        Debug.Log("Executing AppendSingleSkill...");

        GameObject visObj = GameObject.Find(chart_id);
        if (visObj == null)
        {
            Debug.LogWarning("Chart not found: " + chart_id);
            return;
        }

        Vis vis = visObj.GetComponent<Vis>();
        if (vis == null)
        {
            Debug.LogWarning("Vis component not found on: " + chart_id);
            return;
        }

        JSONNode visSpecs = vis.GetVisSpecs();
        if (visSpecs == null)
        {
            Debug.LogWarning("Vis specs is null for chart: " + chart_id);
            return;
        }

        if (visSpecs["encoding"] == null || visSpecs["encoding"]["x"] == null || visSpecs["encoding"]["x"]["field"] == null ||
            visSpecs["encoding"]["y"] == null || visSpecs["encoding"]["y"]["field"] == null)
        {
            Debug.LogWarning("Missing x or y field mapping in vis spec encoding for chart: " + chart_id);
            return;
        }

        string xField = visSpecs["encoding"]["x"]["field"].Value;
        string yField = visSpecs["encoding"]["y"]["field"].Value;
        string xType = (visSpecs["encoding"]["x"]["type"] != null) ? visSpecs["encoding"]["x"]["type"].Value : "nominal";
        string yType = (visSpecs["encoding"]["y"]["type"] != null) ? visSpecs["encoding"]["y"]["type"].Value : "quantitative";

        JSONNode dataValues = visSpecs["data"]["values"];
        if (dataValues == null)
        {
            Debug.LogWarning("No data values found in vis spec for chart: " + chart_id);
            return;
        }

        JSONObject newEntry = new JSONObject();

        if (dataValues.Count > 0)
        {
            foreach (KeyValuePair<string, JSONNode> field in dataValues[0].AsObject)
            {
                newEntry[field.Key] = new JSONString("0");
            }
        }

        if (xType == "quantitative")
        {
            double parsedX;
            if (double.TryParse(x_value, System.Globalization.NumberStyles.Any, System.Globalization.CultureInfo.InvariantCulture, out parsedX))
            {
                newEntry[xField] = new JSONNumber(parsedX);
            }
            else
            {
                Debug.LogWarning("AppendSingleSkill: x_value '" + x_value + "' cannot be parsed as a number for quantitative field.");
                return;
            }
        }
        else
        {
            newEntry[xField] = new JSONString(x_value);
        }

        if (yType == "quantitative")
        {
            double parsedY;
            if (double.TryParse(y_value, System.Globalization.NumberStyles.Any, System.Globalization.CultureInfo.InvariantCulture, out parsedY))
            {
                newEntry[yField] = new JSONNumber(parsedY);
            }
            else
            {
                Debug.LogWarning("AppendSingleSkill: y_value '" + y_value + "' cannot be parsed as a number for quantitative field.");
                return;
            }
        }
        else
        {
            newEntry[yField] = new JSONString(y_value);
        }

        dataValues.Add(newEntry);

        visSpecs["data"]["url"] = new JSONString("inline");

        vis.UpdateVis();

        Debug.Log("AppendSingleSkill completed: chart=" + chart_id + " x=" + x_value + " y=" + y_value);
    }
}

using UnityEngine;
using DxR;
using SimpleJSON;
using System.Collections.Generic;

public class HighlightSkill
{
    private static readonly string LabelTag = "DxRHighlightLabel";

    public static void Execute(string chart_id, string element_id, string highlight_type)
    {
        Debug.Log("Executing HighlightSkill...");

        GameObject visObj = GameObject.Find(chart_id);
        if (visObj == null) { Debug.LogWarning("Chart not found: " + chart_id); return; }

        Vis vis = visObj.GetComponent<Vis>();
        if (vis == null) { Debug.LogWarning("Vis component not found on: " + chart_id); return; }

        int index;
        if (!int.TryParse(element_id, out index))
        {
            Debug.LogWarning("Invalid element_id: " + element_id);
            return;
        }

        if (highlight_type.ToLower() == "none")
        {
            for (int i = 0; i < vis.markInstances.Count; i++)
            {
                RemoveLabel(vis.markInstances[i]);
            }
            Debug.Log("HighlightSkill: removed all labels on chart=" + chart_id);
            return;
        }

        JSONNode visSpecs = vis.GetVisSpecs();
        if (visSpecs == null) { Debug.LogWarning("Vis specs not found."); return; }

        JSONNode dataValues = visSpecs["data"]["values"];
        if (dataValues == null)
        {
            Debug.LogWarning("No data values found in vis spec for chart: " + chart_id);
            return;
        }

        if (index < 0 || index >= dataValues.Count)
        {
            Debug.LogWarning("element_id " + element_id + " out of range (total: " + dataValues.Count + ")");
            return;
        }

        if (index >= vis.markInstances.Count)
        {
            Debug.LogWarning("element_id " + element_id + " out of range in markInstances (total: " + vis.markInstances.Count + ")");
            return;
        }

        string yField = null;
        if (visSpecs["encoding"] != null && visSpecs["encoding"]["y"] != null && visSpecs["encoding"]["y"]["field"] != null)
        {
            yField = visSpecs["encoding"]["y"]["field"].Value;
        }

        string labelText = dataValues[index][yField != null ? yField : ""].Value;
        if (string.IsNullOrEmpty(labelText))
        {
            labelText = "★";
        }

        GameObject targetMark = vis.markInstances[index];
        RemoveLabel(targetMark);
        AttachLabel(targetMark, labelText);

        Debug.Log("HighlightSkill completed. Element=" + element_id + " label=" + labelText + " type=" + highlight_type);
    }

    private static void AttachLabel(GameObject markObj, string text)
    {
        GameObject labelObj = new GameObject(LabelTag);
        labelObj.transform.SetParent(markObj.transform, false);
        labelObj.transform.localPosition = new Vector3(0f, 0.06f, 0f);
        labelObj.transform.localScale = new Vector3(0.0005f, 0.0005f, 0.0005f);

        TextMesh tm = labelObj.AddComponent<TextMesh>();
        tm.text = text;
        tm.fontSize = 80;
        tm.color = Color.yellow;
        tm.anchor = TextAnchor.LowerCenter;
        tm.alignment = TextAlignment.Center;
    }

    private static void RemoveLabel(GameObject markObj)
    {
        Transform existing = markObj.transform.Find(LabelTag);
        if (existing != null)
        {
            GameObject.Destroy(existing.gameObject);
        }
    }
}

using UnityEngine;
using DxR;
using SimpleJSON;
using System.Collections.Generic;
using System.IO;

public class CreateSkill
{
    public static void Execute(string view_id, string data_path, string chart_type, string x_field, string y_field)
    {
        Debug.Log("Executing CreateSkill...");

        if (string.IsNullOrEmpty(view_id))
        {
            Debug.LogWarning("CreateSkill: view_id is null or empty.");
            return;
        }

        if (string.IsNullOrEmpty(data_path))
        {
            Debug.LogWarning("CreateSkill: data_path is null or empty.");
            return;
        }

        if (string.IsNullOrEmpty(x_field) || string.IsNullOrEmpty(y_field))
        {
            Debug.LogWarning("CreateSkill: x_field or y_field is null or empty.");
            return;
        }

        string markType = "bar";
        string chartTypeLower = chart_type != null ? chart_type.ToLower().Trim() : "bar";
        if (chartTypeLower == "point" || chartTypeLower == "scatter")
        {
            markType = "sphere";
        }
        else if (chartTypeLower == "line")
        {
            markType = "bar";
        }
        else if (chartTypeLower == "bar")
        {
            markType = "bar";
        }

        JSONObject specJson = new JSONObject();
        JSONObject dataNode = new JSONObject();
        dataNode["url"] = new JSONString(data_path);
        specJson["data"] = dataNode;
        specJson["mark"] = new JSONString(markType);

        JSONObject encodingNode = new JSONObject();
        JSONObject xEncoding = new JSONObject();
        xEncoding["field"] = new JSONString(x_field);
        xEncoding["type"] = new JSONString("nominal");
        encodingNode["x"] = xEncoding;

        JSONObject yEncoding = new JSONObject();
        yEncoding["field"] = new JSONString(y_field);
        yEncoding["type"] = new JSONString("quantitative");
        encodingNode["y"] = yEncoding;

        specJson["encoding"] = encodingNode;

        string specFileName = view_id + ".json";
        string specFilePath = Parser.GetFullSpecsPath(specFileName);

        try
        {
            File.WriteAllText(specFilePath, specJson.ToString(2));
        }
        catch (System.Exception e)
        {
            Debug.LogWarning("CreateSkill: Failed to write spec file: " + e.Message);
            return;
        }

        GameObject visObj = GameObject.Find(view_id);
        if (visObj != null)
        {
            Vis existingVis = visObj.GetComponent<Vis>();
            if (existingVis != null)
            {
                existingVis.visSpecsURL = specFileName;
                existingVis.UpdateVisSpecsFromTextSpecs();
                Debug.Log("CreateSkill: updated existing vis '" + view_id + "'.");
                return;
            }
        }

        GameObject newVisObj = new GameObject(view_id);

        GameObject dxrView = new GameObject("DxRView");
        dxrView.transform.SetParent(newVisObj.transform, false);

        GameObject dxrMarks = new GameObject("DxRMarks");
        dxrMarks.transform.SetParent(dxrView.transform, false);

        GameObject dxrGuides = new GameObject("DxRGuides");
        dxrGuides.transform.SetParent(dxrView.transform, false);

        GameObject dxrInteractions = new GameObject("DxRInteractions");
        dxrInteractions.transform.SetParent(newVisObj.transform, false);

        GameObject dxrGUI = new GameObject("DxRGUI");
        dxrGUI.transform.SetParent(newVisObj.transform, false);

        Vis vis = newVisObj.AddComponent<Vis>();
        vis.visSpecsURL = specFileName;

        Debug.Log("CreateSkill completed: view=" + view_id + " data=" + data_path + " mark=" + markType + " x=" + x_field + " y=" + y_field);
    }
}
